import manifest from "@/data/image-manifest.json";

/**
 * Typed access to src/data/image-manifest.json (generated by
 * scripts/generate-image-manifest.mjs before every dev/build run).
 */
export type ManifestImage = (typeof manifest.images)[number];

export type GalleryImage = Pick<ManifestImage, "src" | "width" | "height" | "alt" | "blurDataURL" | "category" | "file">;

const byPath = new Map<string, ManifestImage>(manifest.images.map((i) => [i.path, i]));

/** Look up an image by its path under public/images. Fails the build if it is missing. */
export function img(path: string): ManifestImage {
  const found = byPath.get(path.replace(/^\/?images\//, ""));
  if (!found) throw new Error(`Image not found in manifest: ${path}. Run "npm run images:manifest".`);
  return found;
}

/** Shorthand for the migrated 2017 edition photographs. */
export const photo = (n: number) => img(`gallery/2017-chitwan/poultry-${n}.jpg`);

export function galleryImages(): GalleryImage[] {
  return manifest.images
    .filter((i) => i.gallery)
    .map(({ src, width, height, alt, blurDataURL, category, file }) => ({ src, width, height, alt, blurDataURL, category, file }));
}

export const galleryCategories = manifest.categories as Record<string, { label: string; description: string }>;
